export const imageEvents = {workshop:'design',assembly:'launch',launch:'launch',jupiter:'jupiter',saturn:'saturn',rings:'saturn',uranus:'uranus',neptune:'neptune',triton:'triton',io:'jupiter',enceladus:'saturn',miranda:'uranus',uranusRings:'uranus',tritonMosaic:'triton',tritonHorizon:'neptune',heliosphere:'heliopause',record:'record'};
export const events = [
 {id:'design', title:'Замысел и разработка', date:'Конец 1960-х — 1977', text:["Планетное путешествие стало возможным благодаря редкому расположению Юпитера, Сатурна, Урана и Нептуна. При близком пролёте притяжение планеты меняет скорость и направление аппарата относительно Солнца. Такие манёвры позволили добраться до Нептуна примерно за 12 лет.","Изначально NASA утвердила программу исследования Юпитера и Сатурна. Для Voyager 2 с самого начала выбрали путь, который оставлял возможность продолжить экспедицию к двум ледяным гигантам."], photos:['workshop','diagram','assembly']},
 {id:'launch', title:'Подготовка и запуск', date:'20 августа 1977', utc:'1977-08-20T14:29:44Z', text:["20 августа 1977 года ракета Titan IIIE–Centaur стартовала с мыса Канаверал. Voyager 2 запустили первым, но Voyager 1, стартовавший 5 сентября, раньше достиг Юпитера благодаря более короткому маршруту.","На фотографиях можно увидеть, как аппарат поднимали для установки под обтекатель и как ракета уходила со стартовой площадки. После отделения Voyager 2 отправился к первой цели, а связь с ним поддерживала сеть дальней космической связи NASA."], photos:['assembly','launch']},
 {id:'jupiter', title:'Пролёт Юпитера', date:'9 июля 1979', text:["На подлёте камеры следили за движением облаков Юпитера и снимали его крупные спутники. Европу удалось рассмотреть подробнее: на яркой ледяной поверхности видна сеть длинных тёмных линий.","На Ио Voyager 2 повторно заснял активные вулканические шлейфы, впервые замеченные на кадрах Voyager 1. Снимок 9 июля показывает два таких шлейфа у края диска. После сближения с Юпитером зонд направился к Сатурну."], photos:['jupiter','io'], instruments:['ISS','MAG','PLS']},
 {id:'saturn', title:'Пролёт Сатурна', date:'26 августа 1981 UTC', source:sources.pds, text:["У Сатурна Voyager 2 снимал тонкие полосы и неоднородности в его кольцах, а звёздные покрытия помогали определить, где кольца пропускают свет. Камеры также обследовали Тефию, Гиперион и другие спутники.","Мозаика Энцелада показала рядом с кратерами более гладкие области и длинные борозды. По этому различию геологи смогли выделить участки поверхности разного возраста. Путь после Сатурна позволил продолжить миссию к Урану."], photos:['saturn','rings','enceladus'], instruments:['ISS','PPS','PRA']},
 {id:'uranus', title:'Пролёт Урана', date:'24 января 1986', text:["У Урана приборы Voyager 2 обнаружили новые спутники и кольца. Снимки, сделанные из тени планеты, показали слабые пылевые полосы между узкими кольцами. Магнитометр выявил, что магнитная ось сильно наклонена к оси вращения.","На Миранде камеры различили участки рельефа с совсем разным рисунком. Изогнутые гряды одного участка обрываются у границы с соседним, где преобладают кратеры или разломы. Мозаика собрана из кадров, снятых во время пролёта."], photos:['uranus','miranda','uranusRings'], instruments:['ISS','MAG','RSS']},
 {id:'neptune', title:'Пролёт Нептуна', date:'25 августа 1989', text:["Voyager 2 прошёл примерно в 4 800 км над облаками Нептуна, ближе, чем к любой другой планете своего маршрута. На снимках видны Большое тёмное пятно, крупный атмосферный вихрь, и яркие облака рядом с ним.","Зонд исследовал кольца и спутники Нептуна. Геометрия пролёта позволила вскоре приблизиться к Тритону, после чего Voyager 2 ушёл далеко к югу от плоскости земной орбиты."], photos:['neptune','tritonHorizon','triton'], instruments:['ISS','IRIS','MAG','RSS']},
 {id:'triton', title:'Сближение с Тритоном', date:'25 августа 1989', text:["Через несколько часов после Нептуна аппарат прошёл примерно в 40 000 км от Тритона. Снимки показали южную полярную область, покрытую льдом, тёмные полосы на поверхности и активные шлейфы над ней.","Полосы могли образоваться, когда выброшенные частицы осели на лёд. Для цветной мозаики NASA совместила кадры, полученные через три фильтра. Она позволяет различить полярные отложения и типы рельефа."], photos:['tritonMosaic','triton'], instruments:['ISS','UVS']},
 {id:'interstellar', title:'После планетного этапа', date:'С 1989 года', text:["После пролёта Нептуна началась межзвёздная фаза. Учёные следили за тем, как солнечный ветер меняется вдали от Солнца и где его частицы и магнитное поле встречаются с межзвёздной средой.","Когда планетные наблюдения завершились, ключевую роль взяли на себя приборы плазмы, частиц и полей. На иллюстрации NASA видны разные направления полёта двух Voyager и границы гелиосферы."], photos:['heliosphere'], instruments:['LECP','CRS','MAG','PLS','PWS']},
 {id:'shock', title:'Граница ударной волны', date:'2007 год', text:["В 2007 году Voyager 2 достиг области, где поток солнечного ветра резко замедляется. Работающий прибор PLS позволил измерить скорость, плотность и температуру плазмы по обе стороны ударной волны.","Граница встретилась Voyager 2 ближе к Солнцу, чем Voyager 1. Измерения показали асимметрию гелиосферы и дали возможность сравнить её разные области."], source:'https://www.jpl.nasa.gov/news/voyager-2-proves-solar-system-is-squashed/', instruments:['PLS','MAG','CRS']},
 {id:'heliopause', title:'Пересечение гелиопаузы', date:'5 ноября 2018', utc:'2018-11-05T00:00:00Z', approximate:true, text:["5 ноября 2018 года прибор PLS зарегистрировал резкое ослабление потока частиц солнечного ветра. Измерения других приборов подтвердили, что аппарат вошёл в межзвёздную среду.","В момент перехода сигнал добирался до Земли примерно за 16,5 часа. Для сцены выбран расчётный момент начала суток UTC. Дата перехода установлена по измерениям аппарата, а точка в атласе вычислена по эфемеридам."], source:'https://science.nasa.gov/missions/voyager-program/nasas-voyager-2-probe-enters-interstellar-space/', photos:['heliosphere'], instruments:['PLS','CRS','MAG','PWS']},
 {id:'systems', title:'Работа приборов и экономия энергии', date:'1989–2025', text:["Электрическая мощность радиоизотопных генераторов постепенно снижается. Команда миссии перераспределяет питание между системами связи, обогревом и научными приборами.","После планетного этапа наблюдения камерами закончились. Прибор плазмы PLS отключили в 2024 году, а прибор низкоэнергетических заряженных частиц LECP — в 2025-м. Даты и назначение приборов указаны в их карточках."], source:sources.status, instruments:['ISS','IRIS','UVS','PPS','PLS','LECP','PRA','CRS','MAG','PWS']},
 {id:'record', title:'Золотая пластинка', date:'1977 год', text:["Каждый Voyager несёт позолоченную медную пластинку с музыкой, природными звуками, речью и изображениями Земли. На аппарате закреплены игла и защитная крышка с выгравированной инструкцией.","На крышке также есть схема с направлениями на пульсары. Она указывает, откуда отправили послание, а схема атома водорода задаёт единицу времени для расшифровки."], photos:['record'], instruments:['record'], source:sources.record},
 {id:'last', title:'Последняя точка эфемерид', date:'Конец 2099 года', text:["Локальный навигационный набор заканчивается в конце 2099 года. Последняя точка показывает прогноз положения аппарата по расчётам JPL. Сам полёт на этой дате продолжается."]}
];
